-- B10.2 — Owner-managed storefront content and site settings.
--
-- ## Why a key/value table with a typed value, and not a column per field
--
-- The editable surface is genuinely heterogeneous. It spans single scalars
-- ("the announcement text"), small fixed objects ("the hero: eyebrow, headline,
-- accent, description, two CTAs, an image, an aspect ratio"), an ordered list of
-- 4 gallery tiles, an ordered list of 8 FAQ entries, and 4 policy documents of
-- up to 10 ordered sections each. Modelling that as columns would mean either a
-- very wide table mostly NULL, or eight tables that each need their own admin
-- path, their own read, and their own cache invalidation.
--
-- A single `(key, value)` table with an explicit, validated TypeScript schema on
-- top gives one read, one cache tag and one writer, while the *shape* of each
-- document stays typed and checked in application code. The alternative —
-- scattering loose JSON through the app with no schema — is exactly what this
-- avoids: nothing reads `value` without going through `src/lib/site-content.ts`,
-- which parses every document into a declared interface and falls back to the
-- code default when a row is missing or malformed.
--
-- ## Why `value_type` exists
--
-- It is documentation for whoever is looking at the table and a coarse guard
-- against a writer storing the wrong shape, but it is deliberately NOT the
-- validation mechanism: `jsonb` can hold anything, and a SQL CHECK cannot
-- describe these documents. Authoritative validation is in TypeScript, which is
-- where the defaults and the fallbacks already have to live.
--
-- ## Why this is the *content* source of truth and not a layout builder
--
-- Page structure stays in code. There is no "add a section" operation, no block
-- list, no ordering of page components: the keys below are a fixed, closed set
-- that the code knows how to render. The owner edits the words and pictures
-- inside a structure the developer controls. A key that no code reads is inert.
--
-- ## Access model
--
-- Mirrors the catalogue tables exactly:
--   * anon + authenticated get SELECT only — no INSERT/UPDATE/DELETE grant and
--     no write policy, so a browser has no write path at all;
--   * the public read policy is open (all storefront content is public by
--     definition — it is rendered to anonymous visitors), unlike the catalogue
--     where is_active gates visibility. Draft/published state for content is
--     expressed by simply not having saved the change yet, because there is one
--     published copy of each field;
--   * RLS is enabled without FORCE, so the privileged Prisma connection used by
--     the server is unaffected. Every admin write goes through a Server Action
--     that calls `getAdminUser()` first, and reads go through `getSiteContent()`.

create table if not exists public.site_content (
  key         text        primary key,
  value_type  text        not null,
  value       jsonb       not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  -- The key is a dot-delimited path ("home.hero", "page.policy.terms"). The
  -- format is constrained so a typo cannot create an unreachable row that looks
  -- like it should work.
  --
  -- Segments are camelCase or hyphenated: policy keys embed the page's storefront
  -- slug, and slugs are hyphenated by the same rule as
  -- `collections_slug_format` ("page.policy.privacy-policy"), so hyphens have to
  -- be legal here.
  constraint site_content_key_format check (
    key ~ '^[a-z][a-zA-Z0-9]*(\.[a-zA-Z0-9]+(-[a-zA-Z0-9]+)*)*$'
  ),

  constraint site_content_value_type_valid check (
    value_type in ('text', 'boolean', 'number', 'url', 'jsonb')
  ),

  -- An empty key or a JSON `null` document are both ways to "delete" a value
  -- that leave a confusing row behind. Clearing a field is an update to an empty
  -- string (or restoring the code default by deleting the row), never a null.
  constraint site_content_value_not_null check (
    value <> 'null'::jsonb
  )
);

comment on table public.site_content is
  'Owner-managed storefront content and site settings, one row per content document. Read through src/lib/site-content.ts, which owns the typed schema and the code defaults; written only by admin-authorised Server Actions.';
comment on column public.site_content.key is
  'Dot-delimited content path, e.g. home.hero or page.policy.privacy-policy. The set of keys is closed: only keys the code renders have any effect.';
comment on column public.site_content.value is
  'The document itself. Shape depends on the key and is validated in TypeScript, not by a CHECK constraint.';

-- ---------------------------------------------------------------------------
-- updated_at, via the helper the earlier catalogue migrations already install.
-- The trigger function is `public.set_updated_at()` (see 20261004114808).
-- ---------------------------------------------------------------------------
drop trigger if exists set_site_content_updated_at on public.site_content;
create trigger set_site_content_updated_at
  before update on public.site_content
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- RLS + client grants: identical posture to the catalogue tables.
-- ---------------------------------------------------------------------------
alter table public.site_content enable row level security;

revoke all privileges on table public.site_content from anon, authenticated;
grant select on table public.site_content to anon, authenticated;

drop policy if exists site_content_public_read on public.site_content;
create policy site_content_public_read
  on public.site_content
  for select
  to anon, authenticated
  using (true);

-- ---------------------------------------------------------------------------
-- Seed: the content that is hardcoded today, migrated verbatim.
--
-- `on conflict (key) do nothing` makes this re-runnable and, more importantly,
-- makes it a genuine one-time migration: once the owner has edited a document,
-- re-applying this file cannot revert them to the developer's original wording.
-- On a fresh database it installs the current storefront exactly.
--
-- Business details inside policy prose are stored as {{email}}, {{phone}},
-- {{address}}, {{country}} and {{jurisdiction}} tokens rather than resolved
-- text, so the single-source-of-truth property of src/config/business.ts
-- survives: changing the studio's email updates every page that mentions it.
-- They are resolved at render time by src/lib/site-content.ts.
-- ---------------------------------------------------------------------------
insert into public.site_content (key, value_type, value)
