  ('site.nav.mobile', 'jsonb', '[{"label":"Shop","href":"/shop"},{"label":"Collections","href":"/collections"},{"label":"Custom","href":"/custom"},{"label":"Book Appointment","href":"/book-appointment"},{"label":"How It Works","href":"/how-it-works"},{"label":"Size Guide","href":"/size-guide"},{"label":"About","href":"/about"},{"label":"FAQ","href":"/faq"},{"label":"Contact","href":"/contact"}]'::jsonb),
