  ('home.featuredCollection', 'jsonb', '{"eyebrow":"Featured Collection","title":"The Current Edit","description":"A small seasonal series of finishes, shapes, and palettes created by Fufs.","cta":{"label":"Explore Collection","href":"/collections"},"hoverHintLabel":"View Lookbook","imagePath":null,"imageAlt":"Featured collection editorial presentation","imagePlaceholderLabel":"Current Edit Lookbook","imagePlaceholderSublabel":"16:9 • COLLECTION VISUAL","imageRatio":"wide"}'::jsonb),
