  ('home.customFeature', 'jsonb', '{"eyebrow":"Bespoke Requests","title":"Made for your mood.","description":"Have a specific concept, colorway, or event in mind? Work directly with Fufs to create a set tailored to your preferences.","cta":{"label":"Request Custom Set","href":"/custom"},"imagePath":null,"imageAlt":"Custom commission nail design archive","imagePlaceholderLabel":"Custom Commission Archive","imagePlaceholderSublabel":"3:2 • BESPOKE ARCHIVE","imageRatio":"classic"}'::jsonb),
  ('home.howItWorks', 'jsonb', '{"eyebrow":"Guides & Support","title":"Guides","description":"Short, practical answers on sizing, application, delivery and care.","cta":{"label":"Application Guide","href":"/how-it-works"},"links":[{"title":"How It Works","description":"Follow a set from choosing a design to wearing it.","href":"/how-it-works"},{"title":"Size Guide","description":"Measure your natural nails for a comfortable fit.","href":"/size-guide"},{"title":"FAQ","description":"Sizing, fit, application, care and returns.","href":"/faq"},{"title":"Book an Appointment","description":"Have your set applied in person at the studio.","href":"/book-appointment"},{"title":"Shipping & Delivery","description":"Processing times and how orders are sent.","href":"/shipping-policy"},{"title":"Contact the Studio","description":"Ask about a set, an order or a custom idea.","href":"/contact"}]}'::jsonb),
  ('home.gallery', 'jsonb', '{"eyebrow":"Visual Archive","title":"Selected Looks","description":"A curated lookbook of finishes, textures, and custom pieces.","items":[{"key":"gallery-1","ratio":"portrait","label":"Hand Lookbook 01","sublabel":"4:5 • CLOSE LOOK","alt":"Hand editorial nail look","imagePath":null},{"key":"gallery-2","ratio":"square","label":"Texture & Detail","sublabel":"1:1 • MACRO FOCUS","alt":"Nail finish and texture detail","imagePath":null},{"key":"gallery-3","ratio":"square","label":"Packaging & Care","sublabel":"1:1 • FLAT LAY","alt":"Set packaging and prep items","imagePath":null},{"key":"gallery-4","ratio":"portrait","label":"Hand Lookbook 02","sublabel":"4:5 • EDITORIAL","alt":"Alternative editorial nail angle","imagePath":null}]}'::jsonb),
