  ('home.newsletter', 'jsonb', '{"eyebrow":"Studio Updates","title":"Release Announcements","description":"Receive occasional updates when new sets or custom commission slots open.","ctaLabel":"Email to Join the Release List","emailSubject":"Studio release updates"}'::jsonb),
  ('page.faq', 'jsonb', '{"hero":{"eyebrow":"Support & Answers","title":"Frequently Asked Questions","description":"Everything you need to know about our handcrafted press-on sets, sizing, bespoke commissions, and gentle nail care."},"categories":[{"id":"all","label":"All Questions"},{"id":"sets","label":"Sets & Orders"},{"id":"sizing","label":"Sizing & Fit"},{"id":"custom","label":"Custom Requests"},{"id":"care","label":"Application & Care"}],"items":[{"id":"faq-1","category":"sets","question":"What is included with each press-on set?","answer":"Every Nails by Fufs set comes with 10 custom-shaped nail tips, a complete prep kit (wooden cuticle stick, gentle mini buffer, prep wipes), and adhesive application materials (adhesive tabs and nail glue)."},{"id":"faq-2","category":"sets","question":"Are these sets handmade or mass-produced?","answer":"Each set is individually painted, shaped, and top-coated by independent nail artist Fatima in small studio batches. We do not use generic factory-printed plastic tips."},{"id":"faq-3","category":"sizing","question":"How do I find my nail size?","answer":"You can measure the widest part of your natural nail bed using clear tape and a millimeter ruler as shown on our Size Guide page. We also offer standard XS, S, M, and L presets, or you can enter custom millimeter numbers for all 10 fingers."},{"id":"faq-4","category":"sizing","question":"What if my measurements don''t match standard XS–L presets?","answer":"That is completely normal! Many clients have different widths across both hands. You can select ''Custom'' on any product page or custom order request and provide your exact millimeter measurements at no extra charge."},{"id":"faq-5","category":"custom","question":"How do custom design commissions work?","answer":"On our Custom Orders page, you can share your design concept, preferred shape, length, color palette, and upload reference photos or moodboards. Fatima will review your vision and connect directly to confirm details before crafting your set."},{"id":"faq-6","category":"custom","question":"Can I commission nails for a wedding or special event?","answer":"Yes. Bespoke sets for weddings, formal events, and special photoshoots are welcome. We recommend submitting your custom request in advance with any event dates or outfit swatches you''d like to match."},{"id":"faq-7","category":"care","question":"How do I apply press-on nails for the best hold?","answer":"Gently push back cuticles, lightly buff the natural nail surface to remove shine, and wipe clean with the prep pad before applying adhesive tabs or glue. Press firmly for 15–20 seconds per nail."},{"id":"faq-8","category":"care","question":"How do I remove the nails without damaging my natural nails?","answer":"Soak your fingertips in warm soapy water (with a few drops of cuticle oil or baby oil if desired) for 10–15 minutes. The adhesive will soften and the nails will gently lift off without pulling or damage."}],"cta":{"eyebrow":"Have Another Question?","title":"Need something not answered here?","description":"Reach out directly through our contact page or custom order inquiry form. We''re happy to help with sizing, design concepts, or care questions.","primaryCta":{"label":"Contact Studio","href":"/contact"},"secondaryCta":{"label":"Custom Commission","href":"/custom"}},"footerNote":"Each set is individually crafted. Don''t hesitate to contact us if your question isn''t covered above."}'::jsonb),
  ('page.policy.privacy-policy', 'jsonb', '{"eyebrow":"Legal","title":"Privacy Policy","description":"What this website collects, why it is collected, and how it is kept.","intro":["This policy covers this website only. It describes what the site actually does with your information, based on how the storefront and the custom order form are built today."],"sections":[{"id":"who-we-are","heading":"Who we are","paragraphs":["Nails by Fufs is an independent press-on nail studio. Every set is individually painted, shaped and top-coated by artist Fatima in small studio batches — we do not use generic factory-printed plastic tips.","This policy explains what happens to the information you share through this website. The studio''s contact details are listed at the bottom of this page and on our contact page."]},{"id":"what-you-send-us","heading":"What you can send us through this site","paragraphs":["Different parts of the site collect different things. This is what each one asks for and what it is for:"],"bullets":["Custom order requests (the custom order form): your name, email address, an optional Instagram handle or preferred contact; your design preferences — shape, length, sizing option (sizing kit, preset size XS–L, or your own millimetre measurements), optional colour notes, your design description, and optional event date, budget guidance and additional notes; and any reference images you choose to attach.","Bag and checkout: the contents of your bag are stored in your own browser so the bag survives a page reload. At checkout you can enter contact details (name, email, phone) and delivery details (country, street address, optional second address line, city, optional region, optional postal code, optional delivery notes) so an order can be prepared.","Direct contact: if you email or phone the studio using the details published on this site, the studio receives whatever you choose to send in that message so it can reply to you.","Theme preference: whether you prefer the light or dark appearance of the site is stored in your browser only."]},{"id":"what-we-do-not-collect","heading":"What this site does not collect","bullets":["No customer accounts and no passwords — you can use the storefront and send a custom request without registering.","No payment card details. Online payment is not enabled yet, so no card or banking information is requested or stored by this site.","No third-party advertising or analytics trackers. The site does not embed advertising pixels or visitor-analytics scripts."]},{"id":"how-we-use-it","heading":"How your information is used","paragraphs":["Information you send is used only for the purpose you sent it for: reviewing and producing a custom commission, replying to your message, preparing and delivering an order, and keeping the records needed to do those things.","The site runs on Vercel (hosting) and Supabase (database and file storage). These providers process data on the studio''s behalf so the site can operate."]},{"id":"where-it-is-stored","heading":"Where your information is kept","paragraphs":["Custom order requests and the reference images attached to them are stored in the studio''s Supabase project. Reference images are held in a private storage bucket: they are not publicly listed or downloadable, and they are only reachable by the studio through short-lived authorised links.","The contents of your bag and your theme preference never leave your device unless you submit a form.","The checkout step is not connected to the studio''s systems yet, so delivery details entered there are not sent to us and no order is completed through that page."]},{"id":"retention","heading":"How long we keep it","paragraphs":["Custom order requests, the reference images attached to them and related order records are retained only for as long as is reasonably necessary to handle your request, produce your order, maintain business records, or meet legal requirements."]},{"id":"your-requests","heading":"Your choices and requests","paragraphs":["You may contact the studio at any time to request access to the information we hold about you, to request that it be corrected, or to request that it be deleted, where applicable. Email {{email}} or phone {{phone}}, and include the email address you wrote from so your request can be matched to you."]},{"id":"changes","heading":"Changes to this policy","paragraphs":["If this policy changes, the updated version will be published on this page with a new date at the top. Continuing to use the site after an update means the current version applies."]},{"id":"questions","heading":"Questions about this policy","paragraphs":["If anything here is unclear, contact the studio at {{email}} or {{phone}} and we will explain how your information is handled."]}],"metaTitle":"Privacy Policy — Nails by Fufs","metaDescription":"What the Nails by Fufs website collects, why it is collected, and how it is kept — including custom order requests, reference images and delivery details.","lastUpdated":"4 October 2026"}'::jsonb),
  ('page.policy.returns-refunds', 'jsonb', '{"eyebrow":"Legal","title":"Returns & Refunds","description":"How returns, refunds and cancellations work for handcrafted sets.","intro":["This page sets out the studio''s returns, refunds and cancellation terms. Because every set is handmade to the details confirmed with you, these terms are specific rather than general."],"sections":[{"id":"handcrafted","heading":"Every set is handcrafted","paragraphs":["Nails by Fufs sets are not mass-produced. Each set is individually painted, shaped and top-coated by artist Fatima in small studio batches, which is why the studio asks for your shape, length and sizing before a set is made."]},{"id":"sizing-support","heading":"Sizing support comes first","paragraphs":["Most fit problems come from sizing, so the studio offers several ways to get it right before a set is made:"],"bullets":["A complimentary bespoke sizing kit is included with your first order.","You can choose standard XS, S, M or L presets, or enter your own millimetre measurements for all ten nails at no extra charge.","The Size Guide and How It Works pages explain how to measure and how a set is made."]},{"id":"change-of-mind","heading":"Change of mind","paragraphs":["Returns and refunds are not offered for change of mind, or if you simply dislike a set once it arrives. Because each set is made individually to the details confirmed with you, please take a moment over the shape, length and sizing options before an order is placed."]},{"id":"damaged","heading":"If your order arrives damaged","paragraphs":["If a set arrives damaged, contact the studio with your order details and photographs of what arrived. You may request either a refund or a replacement for that order.","Reach the studio at {{email}} or {{phone}}, or through the contact page."]},{"id":"cancellations","heading":"Cancellations","paragraphs":["Once an order is confirmed it cannot be cancelled. If something about your order needs to change, contact the studio as early as possible — but a confirmed order cannot be called off."]},{"id":"raise-a-request","heading":"How to raise a return or refund question","paragraphs":["Contact the studio with your name, the email address you ordered with, and a short description of the issue so it can be matched to your order quickly."],"bullets":["Email: {{email}}","Phone: {{phone}}","Studio: {{address}}"]}],"metaTitle":"Returns & Refunds — Nails by Fufs","metaDescription":"The returns, refund and cancellation terms for handcrafted Nails by Fufs press-on sets, including what to do if an order arrives damaged.","lastUpdated":"4 October 2026"}'::jsonb),
  ('page.policy.shipping-policy', 'jsonb', '{"eyebrow":"Legal","title":"Shipping & Service Policy","description":"How sets are made, sized and delivered — and how to reach the studio about an order.","intro":["This page covers the studio''s service: how a set is made, how sizing is handled, how long processing takes and how orders are delivered."],"sections":[{"id":"handmade-to-order","heading":"Sets are handcrafted in small batches","paragraphs":["Every Nails by Fufs set is individually painted, shaped and top-coated by artist Fatima in small studio batches rather than pulled from mass-produced stock. Each set is prepared for the shape, length and sizing you select before it is sent."]},{"id":"what-is-included","heading":"What comes with a set","paragraphs":["Each set includes ten custom-shaped nail tips, a complete prep kit (wooden cuticle stick, gentle mini buffer and prep wipes) and adhesive application materials (adhesive tabs and nail glue)."]},{"id":"sizing-service","heading":"Sizing service","bullets":["A complimentary bespoke sizing kit is included with your first order.","You can choose standard XS, S, M or L presets, or provide your own millimetre measurements for all ten nails at no extra charge.","The Size Guide explains how to measure, and the How It Works page walks through the studio process."]},{"id":"delivery","heading":"Delivery","paragraphs":["We deliver to major cities across {{country}}.","Delivery normally takes 3–5 days after your order has been processed.","Orders are sent to the delivery address you provide, and the studio contacts you using the email address and phone number supplied with your order if anything needs clarifying."]},{"id":"processing","heading":"Processing time","paragraphs":["Custom orders require 4 days of processing time. Delivery time is additional to that processing period."]},{"id":"custom-commissions","heading":"Custom commissions","paragraphs":["Custom requests are submitted through the custom order form with your concept, preferred shape and length, colour notes and any reference images. Fatima reviews the request and contacts you directly to confirm details before the set is crafted.","If you are commissioning a set for a wedding or a specific event, submit your request in advance — a custom order needs its 4 day processing period before it is sent."]},{"id":"service-contact","heading":"Service contact","paragraphs":["Questions about an order in progress can be raised at any time using the details below."],"bullets":["Email: {{email}}","Phone: {{phone}}","Studio: {{address}}"]}],"metaTitle":"Shipping & Service Policy — Nails by Fufs","metaDescription":"How Nails by Fufs handcrafts, sizes and delivers press-on sets: delivery to major cities across {{country}} within 3–5 days after processing, and 4 days processing for custom orders.","lastUpdated":"4 October 2026"}'::jsonb),
  ('page.policy.terms', 'jsonb', '{"eyebrow":"Legal","title":"Terms & Conditions","description":"The terms that apply to using this site and commissioning a set from the studio.","intro":["These terms describe how the Nails by Fufs website and studio service work."],"sections":[{"id":"about-these-terms","heading":"About these terms","paragraphs":["These terms apply to this website and to requests and orders placed through it. They are written to describe how the storefront and the studio actually work today.","If you do not agree with them, please do not use the site or submit a request."]},{"id":"using-the-site","heading":"Using the site","paragraphs":["The site shows the studio''s catalogue, sizing guidance and custom commission information. You are welcome to browse, and to submit a custom request, for personal use.","You agree not to misuse the site — for example by submitting false information, attempting to interfere with it, or copying its content for commercial use."]},{"id":"orders-and-availability","heading":"Orders and availability","paragraphs":["Sets shown on the site come from the studio''s live catalogue. Designs are made in small batches, so what is shown can change as pieces are made and released.","Online payment is not enabled on this site yet. The checkout page can collect your contact and delivery details, but it does not currently complete an order or send those details to the studio, and no payment is taken through the site.","Until checkout is enabled, the way to order is the custom order form, where Fatima confirms the shape, length, sizing and design details with you directly. Once an order is confirmed it cannot be cancelled — see the Returns & Refunds page for the returns and refund terms."]},{"id":"prices-and-payment","heading":"Prices and payment","paragraphs":["Catalogue prices are not published on the site yet and online payment is not enabled, so nothing is charged through the storefront. Until payment is live, pricing and payment are agreed directly with the studio when your order is confirmed."]},{"id":"custom-commissions","heading":"Custom commissions","paragraphs":["A custom request is a starting point, not a confirmed order. The studio reviews your concept, shape, length, colour notes and reference images, then contacts you directly to confirm the design and sizing before anything is crafted.","Custom orders require 4 days of processing time, and delivery time is additional to that. Once details are confirmed with you, a commission is made to that agreed description."]},{"id":"your-information","heading":"Information you give us","paragraphs":["Please make sure the details you give us are accurate. The measurements you provide are used to make your set, and the delivery address you provide is where it will be sent, so mistakes there affect the finished result.","How your information is handled is described in the Privacy Policy."]},{"id":"designs-and-content","heading":"Designs and site content","paragraphs":["The nail designs, artwork, written content and branding on this site are the studio''s work. Reference images you send stay yours, and are used only to understand and produce your commission."]},{"id":"third-party-links","heading":"Links to other platforms","paragraphs":["The site links to social platforms such as Instagram, TikTok and Pinterest. Those platforms are separate services with their own terms and privacy practices."]},{"id":"changes","heading":"Changes to these terms","paragraphs":["These terms may be updated as the studio''s service and the storefront change. The current version is always published on this page with its date at the top."]},{"id":"governing-law","heading":"Governing law","paragraphs":["Nails by Fufs operates from {{address}}, {{country}}, and these terms are governed by the laws of {{country}}."]}],"metaTitle":"Terms & Conditions — Nails by Fufs","metaDescription":"The terms that apply to using the Nails by Fufs website and commissioning a handcrafted press-on set.","lastUpdated":"4 October 2026"}'::jsonb)
on conflict (key) do nothing;
